/** T50 fallback id for unknown/future icons. */
internal const val CUE_FALLBACK_ID = "note"

/** Resolve an icon id to a known glyph, falling back to [CUE_FALLBACK_ID] (never null). */
internal fun cueGlyph(icon: String): CueGlyph = CUE_GLYPHS[icon] ?: CUE_GLYPHS.getValue(CUE_FALLBACK_ID)
